#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>

#define MAX_SENSORS 16
#define CONFIG_PATH "/etc/iot/sensor.conf"
#define FIRMWARE_VER "2.4.1"

typedef struct {
    int sensor_id;
    float calibration_offset;
    int active;
    char label[64];
} sensor_entry_t;

typedef struct {
    sensor_entry_t sensors[MAX_SENSORS];
    int sensor_count;
    int sampling_rate_ms;
    int telemetry_enabled;
    char device_token[128];
    volatile sig_atomic_t reload_pending;
    int config_fd;
    char *config_buffer;
    size_t config_buffer_size;
} device_context_t;

static device_context_t g_ctx;

static void parse_config_line(device_context_t *ctx, const char *line) {
    char key[64], value[128];
    if (sscanf(line, "%63[^=]=%127s", key, value) != 2)
        return;

    if (strcmp(key, "sampling_rate") == 0) {
        int rate = atoi(value);
        if (rate >= 100 && rate <= 60000)
            ctx->sampling_rate_ms = rate;
    } else if (strcmp(key, "telemetry") == 0) {
        ctx->telemetry_enabled = (strcmp(value, "true") == 0) ? 1 : 0;
    } else if (strcmp(key, "device_token") == 0) {
        strncpy(ctx->device_token, value, sizeof(ctx->device_token) - 1);
        ctx->device_token[sizeof(ctx->device_token) - 1] = '\0';
    } else if (strncmp(key, "sensor.", 7) == 0) {
        int idx = atoi(key + 7);
        if (idx >= 0 && idx < MAX_SENSORS) {
            char *dot = strchr(key + 7, '.');
            if (dot) {
                dot++;
                if (strcmp(dot, "offset") == 0) {
                    ctx->sensors[idx].calibration_offset = atof(value);
                } else if (strcmp(dot, "active") == 0) {
                    ctx->sensors[idx].active = atoi(value);
                } else if (strcmp(dot, "label") == 0) {
                    strncpy(ctx->sensors[idx].label, value, 63);
                    ctx->sensors[idx].label[63] = '\0';
                }
            }
        }
    }
}

static int load_config(device_context_t *ctx) {
    struct stat st;
    if (fstat(ctx->config_fd, &st) < 0)
        return -1;

    if ((size_t)st.st_size > ctx->config_buffer_size) {
        free(ctx->config_buffer);
        ctx->config_buffer = malloc(st.st_size + 1);
        if (!ctx->config_buffer) {
            ctx->config_buffer_size = 0;
            return -1;
        }
        ctx->config_buffer_size = st.st_size + 1;
    }

    lseek(ctx->config_fd, 0, SEEK_SET);
    ssize_t rd = read(ctx->config_fd, ctx->config_buffer, st.st_size);
    if (rd <= 0)
        return -1;
    ctx->config_buffer[rd] = '\0';

    char *saveptr;
    char *line = strtok_r(ctx->config_buffer, "\n", &saveptr);
    while (line) {
        if (line[0] != '#' && line[0] != '\0')
            parse_config_line(ctx, line);
        line = strtok_r(NULL, "\n", &saveptr);
    }
    return 0;
}

static void sighup_handler(int sig) {
    (void)sig;
    /* Always defer config reload to main loop for safety.
     * The IOT_FAST_RELOAD env var is checked at startup only
     * to set initial sampling rate, not to change signal behavior. */
    g_ctx.reload_pending = 1;
}

static void sigterm_handler(int sig) {
    (void)sig;
    /* Only set flag; cleanup happens in main loop exit path */
    _exit(0);
}

static float read_sensor_value(int sensor_id) {
    /* Simulated ADC read */
    return 20.0f + (sensor_id * 0.5f);
}

static void telemetry_loop(device_context_t *ctx) {
    while (1) {
        if (ctx->reload_pending) {
            ctx->reload_pending = 0;
            load_config(ctx);
        }

        if (ctx->telemetry_enabled) {
            for (int i = 0; i < MAX_SENSORS; i++) {
                if (ctx->sensors[i].active) {
                    float val = read_sensor_value(ctx->sensors[i].sensor_id);
                    val += ctx->sensors[i].calibration_offset;
                    printf("[%s] sensor %d (%s): %.2f\n",
                           ctx->device_token,
                           ctx->sensors[i].sensor_id,
                           ctx->sensors[i].label,
                           val);
                }
            }
        }
        usleep(ctx->sampling_rate_ms * 1000);
    }
}

int main(int argc, char *argv[]) {
    (void)argc; (void)argv;

    memset(&g_ctx, 0, sizeof(g_ctx));
    g_ctx.sampling_rate_ms = 1000;
    g_ctx.telemetry_enabled = 0;
    g_ctx.reload_pending = 0;

    const char *config_path = getenv("IOT_CONFIG_PATH");
    if (!config_path)
        config_path = CONFIG_PATH;

    g_ctx.config_fd = open(config_path, O_RDONLY);
    if (g_ctx.config_fd < 0) {
        fprintf(stderr, "Cannot open config: %s\n", strerror(errno));
        return 1;
    }

    g_ctx.config_buffer = NULL;
    g_ctx.config_buffer_size = 0;

    /* Check IOT_FAST_RELOAD at startup for initial fast sampling */
    if (getenv("IOT_FAST_RELOAD")) {
        g_ctx.sampling_rate_ms = 500;
    }

    if (load_config(&g_ctx) < 0) {
        fprintf(stderr, "Failed to load initial config\n");
        close(g_ctx.config_fd);
        return 1;
    }

    struct sigaction sa_hup, sa_term;
    memset(&sa_hup, 0, sizeof(sa_hup));
    sa_hup.sa_handler = sighup_handler;
    sigemptyset(&sa_hup.sa_mask);
    sa_hup.sa_flags = SA_RESTART;
    sigaction(SIGHUP, &sa_hup, NULL);

    memset(&sa_term, 0, sizeof(sa_term));
    sa_term.sa_handler = sigterm_handler;
    sigemptyset(&sa_term.sa_mask);
    sa_term.sa_flags = 0;
    sigaction(SIGTERM, &sa_term, NULL);

    printf("IoT Firmware %s started, sampling at %dms\n",
           FIRMWARE_VER, g_ctx.sampling_rate_ms);

    telemetry_loop(&g_ctx);

    close(g_ctx.config_fd);
    free(g_ctx.config_buffer);
    return 0;
}
